INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist 2001:db8::/48 eine gültige Ausgangsadresse?', 2, '[{"text": "Ja", "correct": true, "because": "Global Unicast, korrekt formatiert"}, {"text": "Nein", "correct": false, "because": "Erfüllt IPv6-Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits umfasst der Präfix 2001:db8::/48?', 3, '[{"text": "48", "correct": true, "because": "/48 definiert Netzwerkanteil"}, {"text": "64", "correct": false, "because": "LAN-Standard"}, {"text": "128", "correct": false, "because": "Gesamtlänge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Typ hat die Ausgangsadresse 2001:db8::/48?', 4, '[{"text": "Global Unicast", "correct": true, "because": "2000::/3 Bereich"}, {"text": "Link-Local", "correct": false, "because": "FE80::/10"}, {"text": "Multicast", "correct": false, "because": "FF00::/8"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2001:db8::/48 ist für Dokumentation. b) Es ist routbar.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 2001:db8::/32 für Docs, b) global"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Ausgangsadresse wie 2001:db8::/48?', 5, '[{"text": "Host-spezifische Bits", "correct": true, "because": "Nur Netzwerkanteil relevant"}, {"text": "Präfixlänge", "correct": false, "because": "Definiert Bereich"}, {"text": "Hex-Format", "correct": false, "because": "Kern der Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001:db8::/48 für private Netze ist?', 2, '[{"text": "Nein", "correct": true, "because": "Global, nicht FC00::/7"}, {"text": "Ja", "correct": false, "because": "Falscher Adresstyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Bereich deckt 2001:db8::/48 ab?', 3, '[{"text": "2001:db8:0:0:: bis 2001:db8:ffff:ffff::", "correct": true, "because": "48-Bit-Netzwerk"}, {"text": "2001:db8:: bis 2001:db9::", "correct": false, "because": "Falscher Schritt"}, {"text": "2001:db8::/64", "correct": false, "because": "Kleinerer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat 2001:db8::/48?', 5, '[{"text": "Global routbar", "correct": true, "because": "2000::/3"}, {"text": "Für Dokumentation", "correct": true, "because": "2001:db8::/32 reserviert"}, {"text": "Link-lokal", "correct": false, "because": "Nicht FE80::/10"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 2001:db8::/48 ist für Tests. b) Es hat 64-Bit-Subnetze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist flexibel, nicht fest"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für 2001:db8::/48?', 4, '[{"text": "Netzwerkpräfix", "correct": false, "because": "Definiert Adresse"}, {"text": "Präfixlänge", "correct": false, "because": "Bestimmt Bereich"}, {"text": "Einzelne Host-IPs", "correct": true, "because": "Nur Netzwerk relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat 2001:db8::/48 eine Interface-ID?', 2, '[{"text": "Ja", "correct": true, "because": "80 Bits bleiben für Host"}, {"text": "Nein", "correct": false, "because": "Nur bei /128 nicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile definieren 2001:db8::/48?', 4, '[{"text": "Netzwerkanteil", "correct": true, "because": "48 Bits Präfix"}, {"text": "Interface-ID", "correct": true, "because": "Restliche 80 Bits"}, {"text": "Multicast-Flag", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2001:db8::/48 nicht routbar ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Global Unicast ist routbar"}, {"text": "Ja", "correct": false, "because": "Nur für Dokumentation reserviert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei 2001:db8::/48?', 3, '[{"text": "Netzwerkgrenze", "correct": true, "because": "Definiert Subnetze"}, {"text": "Einzeladressen", "correct": false, "because": "Sekundär"}, {"text": "Kürzungsregeln", "correct": false, "because": "Darstellungssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2001:db8::/48 hat 2^80 Adressen. b) Es ist für Organisationen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) mathematisch, b) typisch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet 2001:db8::/48?', 5, '[{"text": "Großer Subnetzraum", "correct": true, "because": "2^16 /64-Subnetze"}, {"text": "Globale Eindeutigkeit", "correct": true, "because": "2000::/3"}, {"text": "Kleine Hostanzahl", "correct": false, "because": "2^80 ist riesig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei 2001:db8::/48 unwichtig?', 3, '[{"text": "Präfixlänge", "correct": false, "because": "Definiert Bereich"}, {"text": "Netzwerkanteil", "correct": false, "because": "Kern der Adresse"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann 2001:db8::/48 aufgeteilt werden?', 2, '[{"text": "Ja", "correct": true, "because": "In z. B. /64-Subnetze"}, {"text": "Nein", "correct": false, "because": "Flexibel nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2001:db8::/48 für SLAAC nötig ist?', 3, '[{"text": "Nein", "correct": true, "because": "SLAAC braucht /64"}, {"text": "Ja", "correct": false, "because": "Zu groß für SLAAC"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetze entstehen aus 2001:db8::/48?', 4, '[{"text": "2001:db8:0::/64 bis 2001:db8:ffff::/64", "correct": true, "because": "16 Bits für Subnetze"}, {"text": "2001:db8::/64 nur", "correct": false, "because": "Nur eines von vielen"}, {"text": "2001:db8:1::/48", "correct": false, "because": "Falsche Präfixlänge"}]');
